import{c as t,Q as a,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const s="/assets/docs-teams-list.CzAWM7kV.png",o="/assets/docs-teams-add.BAQ78C3d.png",i="/assets/docs-teams-convert-button.Di3ViAxn.png",h="/assets/docs-teams-team-tab.CQf9wIIu.png",m="/assets/docs-teams-details.CecEPibG.png",d="/assets/docs-teams-member-contacts.CwP9-Hzr.png",l="/assets/docs-teams-convert-back.CW0qotTO.png",g="/assets/docs-teams-results.C5NLlvfO.png",T=JSON.parse('{"title":"Teams that run together","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/teams-that-run-together.md","filePath":"user/running-the-event/teams-that-run-together.md"}'),c={name:"user/running-the-event/teams-that-run-together.md"};function p(u,e,b,y,f,w){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="teams-that-run-together" tabindex="-1">Teams that run together <a class="header-anchor" href="#teams-that-run-together" aria-label="Permalink to &quot;Teams that run together&quot;">​</a></h1><p><strong>Audience:</strong> Organisers taking entries, and operators at the registration desk and the download desk.</p><p>Some entries are several people going round one course together, for one result between them: a family on one card, a pair at a school lesson, a rogaine team, a group of scouts. meshO enters them as a <strong>team</strong>: one competitor that has <strong>members</strong>.</p><p>A team is entered like anybody else. It has one class, one club, one card, one bib, one start and one result. Its card is read like anybody&#39;s, and it is placed in its class like anybody. What a team adds is the people in it: each member has their own name, and can have their own IDs, birth year and sex. A team counts as <strong>one</strong> entry everywhere: in the class&#39;s field size, on the dashboard, in a place, and in every export.</p><blockquote><p><strong>Note:</strong> This isn&#39;t a relay team. In a relay, each runner runs their own leg and has their own result; see <a href="./../event-setup/relay-events">Relay events</a>. A team that runs together goes round as one, so it can only enter an individual class.</p></blockquote><h2 id="the-whole-job" tabindex="-1">The whole job <a class="header-anchor" href="#the-whole-job" aria-label="Permalink to &quot;The whole job&quot;">​</a></h2><ol><li><strong>Add the team.</strong> On <strong>Entries → Teams</strong>, click <strong>Add team…</strong> (or choose <strong>Actions → Add team…</strong> on the Competitors page), type the members&#39; names and give the team its class and card. Or open someone who is already entered and click <strong>Convert to team</strong>.</li><li><strong>Read its card at the finish</strong> like anyone&#39;s. The team gets one result, under its name.</li><li><strong>Check the results.</strong> The team is placed in its class, with its members listed under its name.</li></ol><p>That covers almost every team. The rest of this page shows each screen, and what to do when a team changes.</p><h2 id="the-teams-page" tabindex="-1">The Teams page <a class="header-anchor" href="#the-teams-page" aria-label="Permalink to &quot;The Teams page&quot;">​</a></h2><p><strong>Entries → Teams</strong> lists every team in the event, with its members, class, club, card, start, status and result:</p><p><img src="'+s+'" alt="The Teams page: Dad Bods with Sam Okafor, Rhys Evans and Luca Bianchi; John, Jane &amp; Tim Smith; and Mia Lee &amp; Zoe Park, who have no card or start yet"></p><p>Search finds a team by its name, its bib, or <strong>any member&#39;s name</strong>. Searching for &quot;Zoe Park&quot; finds the team she is in. Click a team&#39;s name to open the team. As on the other lists, drag a heading by its grip to reorder the columns, and turn columns on or off with the columns button at the right-hand end of the header row.</p><p>Teams are on the <strong>Competitors</strong> page too, ticked in its <strong>Team</strong> column, because a team <em>is</em> a competitor. The column appears once the event has a team; the columns button turns it on or off. The search there, at the registration desk and at the download desk also finds a team by a member&#39;s name.</p><p><strong>What to do:</strong> nothing. This page is for finding and adding teams.</p><blockquote><p><strong>Note:</strong> In a relay event, <strong>Entries → Relay teams</strong> lists the relay teams instead. See <a href="./../event-setup/relay-events">Relay events</a>.</p></blockquote><h2 id="adding-a-team" tabindex="-1">Adding a team <a class="header-anchor" href="#adding-a-team" aria-label="Permalink to &quot;Adding a team&quot;">​</a></h2><p>Click <strong>Add team…</strong> on the Teams page, or choose <strong>Actions → Add team…</strong> on the Competitors page.</p><p><img src="'+o+'" alt="The Add team form, with Team and Start tabs down the left. The Team tab: Team name, then one line per member with first name, surname, external ID, IOF ID, birth year and sex, an Add member button, then class, club and card on one line"></p><ol><li><strong>Team name</strong> is optional. Leave it blank and the team is named after its members (see <a href="#how-a-team-is-named">How a team is named</a>); the box shows that name in grey as you type the members.</li><li>Fill in <strong>Member 1</strong>. Typing a first name or surname searches the <a href="./../reference/competitor-registry">Competitor registry</a>. Pick a person there and their IDs, birth year and sex are filled in too, and the team&#39;s <strong>Card number</strong> and <strong>Club</strong> are filled in from theirs if the team has none yet. Every box stays editable, and somebody who isn&#39;t in the registry is typed in as they are.</li><li>Click <strong>Add member</strong> for each person after the first. Each member is one line; the <strong>×</strong> at its end removes them.</li><li>Give the team its <strong>Class</strong>, <strong>Club</strong> and <strong>Card number</strong>, as for anyone.</li><li>If it has an allocated start time, set it on the <strong>Start</strong> tab.</li></ol><p><strong>What to do if it won&#39;t save:</strong> a team needs a team name, or at least one member with a name. Otherwise nothing on a start list could tell it from another team.</p><p>A team can&#39;t enter a relay class. The class list leaves them out.</p><h2 id="how-a-team-is-named" tabindex="-1">How a team is named <a class="header-anchor" href="#how-a-team-is-named" aria-label="Permalink to &quot;How a team is named&quot;">​</a></h2><p>A team with a <strong>Team name</strong> is called by it: <em>Dad Bods</em>. Without one, meshO names it after its members, in the order they&#39;re listed:</p><table tabindex="0"><thead><tr><th>Members</th><th>Name</th></tr></thead><tbody><tr><td>John Smith, Jane Smith</td><td><strong>John &amp; Jane Smith</strong></td></tr><tr><td>John, Jane, Tim and Ava Smith</td><td><strong>John, Jane, Tim &amp; Ava Smith</strong></td></tr><tr><td>Mia Lee, Zoe Park</td><td><strong>Mia Lee &amp; Zoe Park</strong></td></tr><tr><td>Mia Lee, Zoe Park, Sam Okafor</td><td><strong>Mia Lee, Zoe Park &amp; Sam Okafor</strong></td></tr><tr><td>Mia Lee, Zoe Park, Sam Okafor and Ava Reid</td><td><strong>Mia, Zoe, Sam &amp; Ava</strong></td></tr><tr><td>Five Smiths</td><td><strong>John, Jane, Tim, Ava &amp; Max Smith</strong></td></tr></tbody></table><p>A family is put together under the family name. Four or more people from different families are named by their first names alone, so the name fits on a results screen. The name follows the members: change one, and the name changes with them.</p><p>The team&#39;s name is what appears everywhere a competitor&#39;s name does: the results, the screens, commentary, the splits print and every export. The results, the Teams page and the exports also list the members in full.</p><p><strong>What to do:</strong> if the name meshO gives isn&#39;t the one the team uses, type their own in <strong>Team name</strong>.</p><h2 id="turning-an-entry-into-a-team" tabindex="-1">Turning an entry into a team <a class="header-anchor" href="#turning-an-entry-into-a-team" aria-label="Permalink to &quot;Turning an entry into a team&quot;">​</a></h2><p>Somebody entered on their own turns up with a friend, or a parent decides to go round with their child. Open the entry and click <strong>Convert to team</strong>:</p><p><img src="'+i+'" alt="Edit competitor for Alex Johnson, with Convert to team at the foot of the dialog"></p><p>The entry becomes a team, and the person becomes its first member. Everything else stays on the entry: its card, class, club, bib, start, and any result it already has. Add the other people on the <strong>Team</strong> tab.</p><p><strong>What to do:</strong> nothing more. The team keeps its place in the results, under its new name.</p><h2 id="people-who-ran-together-but-were-entered-separately" tabindex="-1">People who ran together but were entered separately <a class="header-anchor" href="#people-who-ran-together-but-were-entered-separately" aria-label="Permalink to &quot;People who ran together but were entered separately&quot;">​</a></h2><p>Two people were entered on their own, went round together, and only one of them has a result. You don&#39;t copy the result across: make them a team, and it belongs to both.</p><ol><li>Open the person whose card was read and click <strong>Convert to team</strong>. The entry keeps its card and its result.</li><li>On the <strong>Team</strong> tab, click <strong>Add member</strong> and add the other person.</li><li>Delete the other person&#39;s own entry, or they stay in the class with no result. If your entries come from Eventor or a file, importing them again adds that entry back.</li></ol><p>The team has one result and one place, in the class of the entry you converted, with everybody&#39;s name under it.</p><p><strong>If the result is on the wrong person</strong>, there&#39;s nothing to copy either: move the download to whoever ran. See <a href="./card-download#the-card-download-detail-dialog">The card download detail dialog</a>. Relay classes can&#39;t hold a team; for a card shared between relay legs, see <a href="./../event-setup/relay-events#one-card-per-leg-shared-and-hire-cards">One card per leg; shared and hire cards</a>.</p><h2 id="editing-the-members" tabindex="-1">Editing the members <a class="header-anchor" href="#editing-the-members" aria-label="Permalink to &quot;Editing the members&quot;">​</a></h2><p>The <strong>Team</strong> tab of Edit competitor has the <strong>Team name</strong> at the top, the same as on <strong>Details</strong>, and lists the members below it. Each one is a person, filled in as a competitor&#39;s name is:</p><p><img src="'+h+'" alt="The Team tab for Dad Bods: Member 1 Sam Okafor, Member 2 Rhys Evans, each with external ID, IOF ID, birth year and sex, and a Remove member button"></p><p><strong>Add member</strong> at the foot adds another person. <strong>Remove member</strong> takes one out; a team keeps at least one member. Changes save as you go, as everywhere in Edit competitor.</p><p>The <strong>Details</strong> tab carries the <strong>Team name</strong> where a person&#39;s name would be, and everything else as for anyone: card, club, bib, class. Left blank, the team is named after its members, shown in grey in the box.</p><p><img src="'+m+'" alt="The Details tab for John, Jane &amp; Tim Smith: Team name left blank and its members&#39; name shown in grey, then card 8301112, club Bushflyers and class Open, and the More details row reading Bib 214"></p><p><strong>Members&#39; emergency contacts and contact details.</strong> Under <strong>More details</strong>, each member the <a href="./../reference/competitor-registry#emergency-contacts">Competitor registry</a> knows has a panel of their own, under their name: their <strong>Contact details</strong> (email, mobile, phone, address and nationality), then their <strong>Emergency contact</strong>. A member the registry holds nothing for shows just &quot;No details recorded in competitor registry&quot;. A member is found in the registry as a competitor is — by their External ID or IOF ID, never by name — so a member typed in by hand with neither has no panel. To change what&#39;s shown, edit the person in the registry.</p><p><img src="'+d+'" alt="More details for John, Jane &amp; Tim Smith: John Smith&#39;s panel with his contact details and then his emergency contact, Jane Smith&#39;s saying No details recorded in competitor registry, and none for Tim, whom the registry doesn&#39;t know"></p><blockquote><p><strong>Note:</strong> The members carry no card. The team runs on one card, and it is the team&#39;s. If each person carried their own card and should get a result of their own, enter them separately instead.</p></blockquote><h2 id="turning-a-team-into-individuals" tabindex="-1">Turning a team into individuals <a class="header-anchor" href="#turning-a-team-into-individuals" aria-label="Permalink to &quot;Turning a team into individuals&quot;">​</a></h2><p>On the <strong>Team</strong> tab of Edit competitor, click <strong>Convert to individuals</strong>, below the members. With one member, that person becomes the entry. With more, meshO asks who keeps the entry:</p><p><img src="'+l+'" alt="Convert to individuals: Sam Okafor chosen to keep the entry; Rhys Evans and Luca Bianchi listed as the members who become competitors of their own"></p><p>The person you choose keeps the entry: its card, bib, start and result. Every other member becomes a <strong>competitor of their own</strong>, in the same class and club, with their own IDs, birth year and sex, but <strong>no card, bib or start</strong>. Two entries on one card would both be scored on its punches, so only one of them can keep it.</p><p><strong>What to do:</strong> give each new competitor their own card (and a start time, if your starts are allocated) before they run. Nobody is merged: two entries are never made into one.</p><p><strong>Add team</strong> has no <strong>Convert to individuals</strong>: to enter the people on their own instead, click <strong>Cancel</strong> and add each one with <strong>Add competitor…</strong>.</p><h2 id="the-results" tabindex="-1">The results <a class="header-anchor" href="#the-results" aria-label="Permalink to &quot;The results&quot;">​</a></h2><p>A team is placed in its class with everybody else in it, and its members are listed under its name:</p><p><img src="'+g+'" alt="Results for Open: 1 Dad Bods 27:48.0, with Sam Okafor, Rhys Evans and Luca Bianchi under it; 2 Riley Davis; 3 John, Jane &amp; Tim Smith with the three Smiths under it; 4 Quinn Patel"></p><p>A members line appears on the spectator site, the kiosk, the results PDF and the printed results. Usually a team goes in a class of its own, such as a <em>Family</em> or <em>Groups</em> class, so it is placed against other teams rather than against people running alone. Nothing requires that, though.</p><h2 id="files-and-other-systems" tabindex="-1">Files and other systems <a class="header-anchor" href="#files-and-other-systems" aria-label="Permalink to &quot;Files and other systems&quot;">​</a></h2><p>A team survives every round trip. Export it and import the file back, and the same team comes back with the same members.</p><table tabindex="0"><thead><tr><th>Where</th><th>How a team is written</th></tr></thead><tbody><tr><td><strong>IOF XML</strong> (entry list, start list, results)</td><td>A <code>TeamEntry</code>, <code>TeamStart</code> or <code>TeamResult</code> whose members all run leg 1, in <code>LegOrder</code> 1, 2, 3…. This is how the standard writes people running a leg together. Importing such a team from another system&#39;s file gives a team that runs together. A relay team with only its first runner entered stays a relay team.</td></tr><tr><td><strong>Orienteering JSON</strong></td><td>The entry, with the team&#39;s <strong>teamName</strong> and <strong>members</strong> beside it. See <a href="./../advanced/orienteering-json#entries">Orienteering JSON</a>.</td></tr><tr><td><strong>CSV</strong></td><td>One row per member, each with the team&#39;s card, class and club, plus a <strong>Team bib</strong> and a <strong>Team name</strong> column. On import, rows with the same team bib (or, with no bib, the same team name) in a class become one team. Rows of one team that name <strong>different cards</strong> are refused, and the import&#39;s warnings name the rows. A team runs on one card, and the file doesn&#39;t say which.</td></tr><tr><td><strong>Eventor results upload</strong></td><td>One result, named for the team (<em>Dad Bods</em>, or <em>John &amp; Jane Smith</em>), with no person ID. Eventor has no result for a team in an individual class, and filing the team&#39;s result under one member would credit that person alone.</td></tr><tr><td><strong>ANNE results upload</strong></td><td>A <code>TeamResult</code>, as in the IOF XML file.</td></tr></tbody></table><p><strong>What to do when a CSV import warns about a team:</strong> open the file, give every row of that team the same card (or leave all but one blank) and import it again.</p><p>A re-imported CSV finds each team again by its card, or, with no card, by its name, as it finds a person. A re-import updates the team rather than adding a second one. A member keeps their IDs, birth year and sex through a re-import, even though the CSV has no column for the last two.</p><h2 id="what-a-team-can-t-do-yet" tabindex="-1">What a team can&#39;t do yet <a class="header-anchor" href="#what-a-team-can-t-do-yet" aria-label="Permalink to &quot;What a team can&#39;t do yet&quot;">​</a></h2><ul><li><strong>Be carried to the next stage of a multi-stage event.</strong> When entries are copied from one stage to the next, teams are left behind, and the copy says how many. Enter them on the new stage again. See <a href="./../event-setup/multi-stage-events">Multi-stage events</a>.</li><li><strong>Have a bib in an IOF XML entry list.</strong> The format has nowhere for one, for a team or for a person; see <a href="./../event-setup/competitors-clubs-teams#what-the-iof-xml-file-leaves-out">What the IOF XML file leaves out</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a></li><li><a href="./../event-setup/relay-events">Relay events</a></li><li><a href="./registration-desk">The registration desk</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./../event-setup/import-event-data">Importing event data</a></li><li><a href="./../advanced/orienteering-json">Orienteering JSON</a></li></ul>',65)])])}const k=t(c,[["render",p]]);export{T as __pageData,k as default};
